INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Hormone therapy for transgender people', 'hormone-therapy-for-transgender-people', '<p> </p>
<div></div>
<div><a href="https://4.bp.blogspot.com/-hJ4m6ww-3YQ/Udv_XlmJfoI/AAAAAAAAAy4/_z8L5F5JSMg/s1600/Transgender+conference+2.jpg"><img loading="lazy" decoding="async" border="0" height="255" src="https://4.bp.blogspot.com/-hJ4m6ww-3YQ/Udv_XlmJfoI/AAAAAAAAAy4/_z8L5F5JSMg/s320/Transgender+conference+2.jpg" width="320" /></a></div>
<p></p>
<div><span>&#8216;</span>Transgender Healthcare’ was the&nbsp;focus of the Transgender South-East Conference 2013.&nbsp;<span>Held in February</span><span>, it aimed to de-mystify the healthcare needs of transgender people and their families.</span><br /><span><span>Participants heard that 32% of health and social care workers had provided treatment to a transgender person, but only 10 per cent of them had any training in the issues involved.</span><span>*</span></span></div>
<div><span><b>REPORT BY ROBERT McNAMARA.</b></span><br /><a name=''more''></a><span><b><o:p></o:p></b></span></p>
</div>
<div>The conference was attended by 140 people and supported through funding from Waterford Area Partnership (WAP).“This year we targeted transgender healthcare, focusing on best practice worldwide to facilitate a learning process for service providers that never existed before in Ireland,” said organiser Vanessa Lacey of Transgender Equality Network Ireland (TENI).</div>
<div>
<p><span></span><br /><span><o:p></o:p></span></div>
<div><span>Guest speaker Dr Jamison Green of the World Professional Association of Transgender Health talked of international best practice. <o:p></o:p></span></div>
<div><span>Among other guest speakers was Dr. Thomas Ahern of St Colmcille’s Hospital, Loughlinstown, who spoke about endrocrinology and hormone therapy for transgender people in Ireland.<o:p></o:p></span></div>
<div><span>The day was facilitated by a partnership between WAP, the HSE, TENI and TRANSE, a community group supporting transgender people in the South East.<o:p></o:p></span></div>
<div><span>The chairperson of the Oireachtas Committee for Health and Children, Jerry Buttimer, TD, opened the conference.<o:p></o:p></span></div>
<div><b><span>Should workers in other communities have any queries, contact WAP directly. T: 051-841740. E: </span></b><span><a href="mailto:info@wap.ie"><b>info@wap.ie</b></a><b> W: www.wap.ie<o:p></o:p></b></span></div>
<div><span><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span></span></span><span>The </span><span>HSE Transgender Health Advisory Group carried out a survey in 2012 among health and social care workers and 41% of respondents described their knowledge of transgender health issues as poor or non-existent.<o:p></o:p></span></div>
<div></div>
<p></p>', '‘Transgender Healthcare’ was the focus of the Transgender South-East Conference 2013. Held in February, it aimed to de-mystify the healthcare needs of transgender people and their families.Participants heard that 32% of health and social care workers had provided treatment to a transgender person, but only 10 per cent of them had any training in the issues involved.*', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 157, 1, '2013-07-09T04:30:00Z', '2013-07-09T04:30:00Z', '2013-07-09T04:30:00Z')
