INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Speed dating for community groups', 'speed-dating-for-community-groups', '<p> </p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-h9ooBdjmA3w/UdrGkD-VYxI/AAAAAAAAAyQ/4vgGYtdappQ/s1600/MAKING+THE+LINK.jpg"><img loading="lazy" decoding="async" border="0" height="241" src="https://3.bp.blogspot.com/-h9ooBdjmA3w/UdrGkD-VYxI/AAAAAAAAAyQ/4vgGYtdappQ/s400/MAKING+THE+LINK.jpg" width="400" /></a></td>
</tr>
<tr>
<td><span><i><span><span>L-R: Susan Power, Waterford City Childcare Committee; Eilishe O’Keeffe, Brothers of Charity; John McDonald,&nbsp;Waterford Disability Network; Fiona Lewis, South East Simon; Paul Murphy, Waterford Warmer Homes.</span></span></i></span>   </td>
</tr>
</tbody>
</table>
<p></p>
<div><b><span>Might a replacement have been found for C&amp;V sector “open days” held at local level where every organisation has a stall in a hall?&nbsp;</span></b><br /><b><span>ROBERT McNAMARA REPORTS:</span></b><br /><a name=''more''></a><b><span><o:p></o:p></span></b></div>
<div><span>Last May,&nbsp;</span>Waterford Area Partnership (WAP)&nbsp;&nbsp;hosted ‘Making the Link’ a speed-dating event for community groups where each group’s rep has two minutes to woo the ‘dates’ from other community organisations.</div>
<div><span><span>The café style networking event took place in the Edmund Rice Heritage Centre, Barrack St in Waterford City and was a huge success according to Margaret Mulligan </span></span><span><span>LCDP Coordinator at</span></span><span><span> WAP.<o:p></o:p></span></span></div>
<div><span><span>“It allowed each participant to meet representatives from all the other organisations and gave them the opportunity to share information on the&nbsp;work they do. They were also able to&nbsp;exchange ideas and share contact details,” she said.</span></span><br /><span><span><o:p></o:p></span></span></div>
<div><span><span>“Many of the participants were really amazed at the number of groups&nbsp;active in the city and the wide range of work that they do. They&nbsp;were delighted to meet people from other organisations&nbsp;who would be able to offer valuable support in the future,”&nbsp;Margaret added.</span></span></div>
<p><o:p></o:p></p>
<div><span><span>Anna Walsh from the Money Advice and Budgeting Service said, “It was great to be able to put faces to the names that I have been dealing with over the phone, the event was very worthwhile”.<o:p></o:p></span></span></div>
<div><span><span>The event was open to community and voluntary groups and the main statutory agencies.&nbsp;</span></span><span><o:p></o:p></span></div>
<div><span><span>“The dramatic increase in demand for assistance, information and support from state services is placing enormous pressure on their frontline staff. This can be very frustrating and time-consuming. Identifying the right person or section in an organisation can help reduce delays and get accurate information quicker.&nbsp; Community groups found the event to be of real benefit in helping to build contacts in the statutory sector,” said Jack Walsh of WAP.<o:p></o:p></span></span></div>
<div><span><span>WAP have also published a “Guide to Services” leaflet for the Waterford area which includes everything from social welfare to recreational facility contact details. This is in addition to the website <a href="https://www.waterfordlife.ie/">www.waterfordlife.ie</a>, which can be used to access information about services in the city.<o:p></o:p></span></span></div>
<div><span><b><span>Note: WAP’s speed-dating style events were held in pursuit of LCDP Goal 1 which seeks to “promote awareness, knowledge and uptake of a wide range of statutory, voluntary and community services.”<o:p></o:p></span></b></span></div>
<p></p>', 'L-R: Susan Power, Waterford City Childcare Committee; Eilishe O’Keeffe, Brothers of Charity; John McDonald, Waterford Disability Network; Fiona Lewis, South East Simon; Paul Murphy, Waterford Warmer Homes. Might a replacement have been found for C&V sector “open days” held at local level where every organisation has a stall in a hall? ROBERT McNAMARA REPORTS: Last May, Waterford Area', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 159, 1, '2013-07-09T04:00:00Z', '2013-07-09T04:00:00Z', '2013-07-09T04:00:00Z')
