INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Kerryman’s ‘Penrelief’ idea', 'kerrymans-penrelief-idea', '<p></p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-lDar9kpuRoA/UdqsHxj12XI/AAAAAAAAAyA/we5z60u_Q7w/s1600/GerCollins.jpg"><img loading="lazy" decoding="async" border="0" height="320" src="https://3.bp.blogspot.com/-lDar9kpuRoA/UdqsHxj12XI/AAAAAAAAAyA/we5z60u_Q7w/s320/GerCollins.jpg" width="309" /></a></td>
</tr>
<tr>
<td>Ger Collins, founder of penrelief.com</td>
</tr>
</tbody>
</table>
<p><b> </b></p>
<div><span>A new ‘get-it-off-your-chest’ website set up in March has got people from Ireland and <a href="https://www.exactreplicawatch.com/product-category/rolex/">rolex bracelet replica</a> around the world writing about their mental health challenges, <b>REPORTS ALLEN MEAGHER.<o:p></o:p></b></span></div>
<div><span>It’s attracted the attention of two </span><span>major suicide prevention agencies which are in discussions with the founder, while a cancer support group are going to take the idea and adapt it for their own use.</span><br />
<a name="more"></a><span><o:p></o:p></span></div>
<div><span>Penrelief.com was set up by Tralee-based Ger Collins who says that putting his thoughts into words was very beneficial in helping <a href="https://www.alexandermcqueenreplica.re/product/788089-alexander-mcqueen-casual-shoes-for-women/">788089 alexander mcqueen casual shoes for women</a> him overcome his own mental health problems.<o:p></o:p></span></div>
<div><span>Ger, who is the chairperson of Shanakill Family Resource Centre, has a team of volunteers involved in the project. <o:p></o:p></span></div>
<div><span>“I’m not a counsellor and I refer people onto professionals when I can,” says Ger. “Seven people have gone into counselling since the site was launched, people who wouldn’t have done so otherwise.” <o:p></o:p></span></div>
<div><span>Singer and addiction counselor, Frances Black, recently endorsed the site which had over 5,000 ‘hits’ in its first month.<o:p></o:p></span></div>
<div><b><span>To contact Ger Collins, email penrelief@gmail.com or ring </span></b><b><span>087-683-9713.</span></b><b><span><o:p></o:p></span></b></div>
<p></p>', 'Ger Collins, founder of penrelief.com A new ‘get-it-off-your-chest’ website set up in March has got people from Ireland and rolex bracelet replica around the world writing about their mental health', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 158, 1, '2013-07-09T04:00:00Z', '2023-12-15T01:34:01Z', '2013-07-09T04:00:00Z')
