INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Kerry village wins unique prize', 'kerry-village-wins-unique-prize', '<p> </p>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-8FgW1yXxfBg/UdqrSuLQCfI/AAAAAAAAAxw/uszLehkRpMY/s1600/mary+and+dan.jpg"><img loading="lazy" decoding="async" border="0" height="254" src="https://4.bp.blogspot.com/-8FgW1yXxfBg/UdqrSuLQCfI/AAAAAAAAAxw/uszLehkRpMY/s320/mary+and+dan.jpg" width="320" /></a></td>
</tr>
<tr>
<td><span>Mary McEvoy&nbsp;with Dan O’ Connor, development manager with&nbsp;Kerry Mental Health Association, in Ballyduff on March 14<sup>th</sup>. </span><span lang="EN-GB">Photo by</span><span>&nbsp;Oskars&nbsp;Krastins.</span>   </td>
</tr>
</tbody>
</table>
<p></p>
<div><span lang="EN-GB">A village in North Kerry has won an unique prize, courtesy of North East Kerry Development working with an inter-agency committee.<o:p></o:p></span></div>
<div><span lang="EN-GB">Ballyduff won a </span><span>programme to become a ‘Community of Excellence’ in promoting mental&nbsp;health awareness and well-being. It involves bringing as much training, talks and fun events to the village as possible, all tailored to the village’s needs and requests.</span><br /><a name=''more''></a><span lang="EN-GB"><o:p></o:p></span></div>
<div><span lang="EN-GB">The one-year pilot programme was launched in style by actress and author Mary McEvoy on March 14<sup>th</sup> </span><span>and, i</span><span lang="EN-GB">n a show of support on the night, every one of the 140 seats in Ballyduff Community Centre was occupied.</span><br /><span lang="EN-GB"><o:p></o:p></span></div>
<div><span lang="EN-GB">“On the night, Mary spoke about her own experiences of depression,” reported </span><span>Lorraine Bowler of NEKD. “She </span><span lang="EN-GB">told Ballyduff how lucky they were to have this project, saying if she had this kind of support when she was younger the sky would have been the limit for her.”<o:p></o:p></span></div>
<div><span lang="EN-GB">Mary’s</span><span> book ‘How the Light Gets In’ describes her own struggles.<o:p></o:p></span></div>
<div><span lang="EN-GB">In the short time since the launch the village has held three more events while others are in the pipeline.<o:p></o:p></span></div>
<div><span>Ballyduff won the unusual prize after </span><span>villages in North Kerry were asked to<span>&nbsp; </span>apply and compete with each other. They had to say how they thought their community would&nbsp;benefit from the kind of programme on offer.</span></div>
<p><span><o:p></o:p></span></p>
<div><span>A new local group now develops ideas suggested by the local community and they are aiming for “a community where all ages come together to support each other as we build on our ability to become more resilient in challenging times by continuing to learn and to grow.”<o:p></o:p></span></div>
<div><span>NEKD say, that if</span><span> the pilot proves successful, similar projects may be rolled out in villages across North Kerry and possibly nationwide.<o:p></o:p></span></div>
<div><span>“The project is about people striving for a more connected society and living life as happily as we can,” says </span><span>Lorraine “We would hope other Local development&nbsp;companies around the country might take this up in the future.”<o:p></o:p></span></div>
<div><span lang="EN-GB">The Institute of Technology Tralee (ITT) is helping to monitor and evaluate the project as it unfolds, while former trainer to the Cork Senior Hurling Team, Jerry Wallace, is lending his support. He currently trains the Ballyduff hurlers.<o:p></o:p></span></div>
<div><strong><span lang="EN-GB">At the launch night, information stands were staffed by folks from: Kerry Mental Health Association, Console, the Openarms Project, Pieta House, Living Links, Buds FRC, the HSE, the Samaritans, Kerry Travellers Development Group, the Social Health and Education Project, North East Kerry Development (NEKD) and a host of other agencies and organisations eager to be involved.</span></strong><span lang="EN-GB"><o:p></o:p></span></div>
<div><span lang="EN-GB">Since the launch, Ballyduff has organised three more events and it plans to run personal development courses, a mindfulness workshop, a ‘Mind Yourself’ programme and a family fun day shortly.<o:p></o:p></span></div>
<div><b><span lang="EN-GB">The project is hosted by Buds Family Resource Centre. T: 066-7148883.<o:p></o:p></span></b></div>
<p></p>', 'Mary McEvoy with Dan O’ Connor, development manager with Kerry Mental Health Association, in Ballyduff on March 14th. Photo by Oskars Krastins. A village in North Kerry has won an unique prize, courtesy of North East Kerry Development working with an inter-agency committee. Ballyduff won a programme to become a ‘Community of Excellence’ in promoting mental health awareness and well-being.', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 160, 1, '2013-07-08T12:08:00Z', '2013-07-08T12:08:00Z', '2013-07-08T12:08:00Z')
