INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Alignment – For and Against', 'alignment-for-and-against', '<p>  </p>
<div><a href="https://3.bp.blogspot.com/-V1FenKNGi0A/UbHgKmcB9tI/AAAAAAAAAvQ/Fm9Smo3SLgs/s1600/for+and+agt.png"><img loading="lazy" decoding="async" src="https://3.bp.blogspot.com/-V1FenKNGi0A/UbHgKmcB9tI/AAAAAAAAAvQ/Fm9Smo3SLgs/s320/for+and+agt.png" width="320" height="174" border="0" /></a></div>
<div><span><b><span>IN FAVOUR:</span></b><span> “</span><span>This document represents a fundamental re-imagining of the system and it sees local government leading economic, social and community development</span><span>… </span><span>Unlike many previous reform documents, this Programme sets out firm decisions by Government rather than proposals for discussion.”</span></span></div>
<div><span><b><i><span>&#8211; </span></i></b><b><span>Minister for the Environment, Community and Local Government, Phil Hogan.</span></b></span></div>
<div><span> </span></div>
<div><span><b><span>OPPOSED:</span></b> <span>“While we recognise the need for stronger and more accountable local government, we caution against any attempt to subsume community-led local development bodies into local authorities.”</span></span></div>
<div><b><i><span lang="EN-GB">&#8211; 21 academics writing in the Irish Times.</span></i></b></div>
<div><span> </span></div>
<div><b></b><br />
<a name="more"></a><span><b><span>IN FAVOUR: </span></b><span>“It is evident that the existing arrangements for local development are administratively burdensome and do not lend themselves to joined-up, integrated service delivery</span><span>, having evolved from a disjointed national approach to local service delivery. Central government, by establishing multiple structures for service delivery at local level has, to a large extent, by-passed local government and undermined the democratic process at local level. </span><span>”</span></span></div>
<div><b><span>&#8211; Final Report of the Local Government/Local Development Alignment Steering Group.</span></b></div>
<div><span> </span></div>
<div><span><b><span>OPPOSED:</span></b> <span>“They’ve already torn the bottom out of it.”</span></span></div>
<div><span><b><span>&#8211; CEO of a local development company who requested anonymity.</span></b><b><i></i></b></span></div>
<div><span><br />
</span><span><br />
</span></div>
<div><span><b><span>IN FAVOUR:</span></b> <span>“The contention that 2,000 jobs will be lost and that 20 years of experience in the planning and delivery of local development programmes will be lost is quite simply untrue.”</span></span></div>
<div><b><span>&#8211; Áine Collins, Fine Gael TD<span>                  </span></span></b></div>
<div><span> </span></div>
<div><span><b><span>OPPOSED:</span></b><span> “They need to build it from the ground up. Generally, top-down policies haven’t worked for communities and are too weak.”</span></span></div>
<div><b><span><span>&#8211; Maria Power, community consultant based in Youghal, Co. Cork.</span></span></b></div>
<p></p>', 'IN FAVOUR: “This document represents a fundamental re-imagining of the system and it sees local government leading economic, social and community development… Unlike many previous reform documents, this Programme sets out firm decisions by Government rather than proposals for discussion.” – Minister for the Environment, Community and Local Government, Phil Hogan. OPPOSED: “While we', 'https://changingireland.ie/wp-content/uploads/2017/06/Iss-2B57-2Brural-2Bbldgs-2Btony-2Bgrehan.jpg', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 166, 1, '2013-06-07T13:29:00Z', '2019-07-09T16:11:18Z', '2013-06-07T13:29:00Z')
