INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('On the web relating to Alignment', 'on-the-web-relating-to-alignment', '<p>     </p>
<h2><b><i><u><span>REPORTS, ANALYSIS, RESPONSES </span></u></i></b></h2>
<div><a href="https://1.bp.blogspot.com/-aBX9jENvGPQ/UbHbycsL7xI/AAAAAAAAAvA/Oi4br8c8JBE/s1600/Information.png"><img loading="lazy" decoding="async" border="0" height="312" src="https://1.bp.blogspot.com/-aBX9jENvGPQ/UbHbycsL7xI/AAAAAAAAAvA/Oi4br8c8JBE/s320/Information.png" width="320" /></a></div>
<div><span><b><i>The following are links to 30 or so online news reports, academic articles and Government papers. Along with our own sources and a review or Oireachtas debates, they helped inform &#8216;Changing Ireland&#8217;s reportage on local government reform and the debate around &#8216;alignment&#8217;:</i></b></span><br /><a name=''more''></a></div>
<div><span><b><i><br /></i></b></span></div>
<div><b><i><span>‘Final Report of the Local Government/Local Development Alignment Steering Group, March 2012’<o:p></o:p></span></i></b></div>
<div><i><span>https://www.environ.ie/en/Publications/LocalGovernment/Administration/FileDownLoad,31308,en.pdf<o:p></o:p></span></i></div>
<div></div>
<div><b><i><span>‘A Guide to Putting People First’<o:p></o:p></span></i></b></div>
<div><i><span><a href="https://www.environ.ie/en/LocalGovernment/LocalGovernmentReform/PublicationsDocuments/FileDownLoad,31310,en.pdf">https://www.environ.ie/en/LocalGovernment/LocalGovernmentReform/PublicationsDocuments/FileDownLoad,31310,en.pdf</a><o:p></o:p></span></i></div>
<div></div>
<div><b><i><span>‘Putting People First’<o:p></o:p></span></i></b></div>
<div><i><span><a href="https://www.rte.ie/news/2012/1016/puttingpeoplefirst.pdf">https://www.rte.ie/news/2012/1016/puttingpeoplefirst.pdf</a><o:p></o:p></span></i></div>
<div><i><span>OR <a href="https://www.environ.ie/en/Publications/LocalGovernment/Administration/FileDownLoad,31309,en.pdf">https://www.environ.ie/en/Publications/LocalGovernment/Administration/FileDownLoad,31309,en.pdf</a>(Note: This link was broken as of mid-May 2013)<o:p></o:p></span></i></div>
<div></div>
<div><b><i><span>‘Putting in Place Jobs that Last &#8211; A Guide to Rebuilding Quality Employment at Local Level’, by Francesca Froy and Sylvain Giguère, published in OECD LEED Working Papers, 2010/13.<o:p></o:p></span></i></b></div>
<div><i><span><a href="https://dx.doi.org/10.1787/5km7jf7qtk9p-en">https://dx.doi.org/10.1787/5km7jf7qtk9p-en</a><o:p></o:p></span></i></div>
<div></div>
<div><b><i><span>Report on Local Authority Support to Economic Development<o:p></o:p></span></i></b></div>
<div><b><i><span><span>&nbsp;</span>&#8211; County and City Managers’ Association.<o:p></o:p></span></i></b></div>
<div><i><span><a href="https://www.lgma.ie/en/news/ccma-report-local-authorities-support-economic-development">https://www.lgma.ie/en/news/ccma-report-local-authorities-support-economic-development</a><o:p></o:p></span></i></div>
<div></div>
<div><b><i><span>Supporting Enterprise, Local Development and Economic Growth – Analysis of Local Authority Activities for 2012<o:p></o:p></span></i></b></div>
<div><b><i><span>&#8211; a report from the County and City Managers’ Association.<o:p></o:p></span></i></b></div>
<div><b><i><span><a href="https://www.lgma.ie/sites/default/files/newsfiles/supporting_enterprise_local_development_and_economic_growth_2012.pdf">https://www.lgma.ie/sites/default/files/newsfiles/supporting_enterprise_local_development_and_economic_growth_2012.pdf</a><o:p></o:p></span></i></b></div>
<div></div>
<div><b><i><span>‘Responding to Alignment / Putting People First – Position on Key Proposals’<o:p></o:p></span></i></b></div>
<div><b><i><span>&#8211; ILDN, November 2012<o:p></o:p></span></i></b></div>
<div><i><span><a href="https://www.ildn.ie/sites/default/files/responding_to_alignment_-_ildn_position_on_key_proposals_21.11.12.pdf">https://www.ildn.ie/sites/default/files/responding_to_alignment_-_ildn_position_on_key_proposals_21.11.12.pdf</a><o:p></o:p></span></i></div>
<div></div>
<div><b><i><span>‘Alignment, Autonomy and Accountability? What now for Community Development?’ <o:p></o:p></span></i></b></div>
<div><b><i><span>&#8211; a report from a conference in November 2012 in NUI Maynooth<o:p></o:p></span></i></b></div>
<div><i><span><a href="https://www.cwc.ie/wp-content/uploads/2012/11/NUIM_Report_web2.pdf">https://www.cwc.ie/wp-content/uploads/2012/11/NUIM_Report_web2.pdf</a><o:p></o:p></span></i></div>
<div></div>
