INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Alignment in more detail: The role and functions of Socio-Economic Committees', 'alignment-in-more-detail-the-role-and-functions-of-socio-economic-committees', '<p>     </p>
<div><a href="https://2.bp.blogspot.com/-xO0RyR4gkCM/UbHV-vzF2oI/AAAAAAAAAuA/Gnd5sqevqro/s1600/Alignment+can+be+tricky.png"><img loading="lazy" decoding="async" border="0" height="309" src="https://2.bp.blogspot.com/-xO0RyR4gkCM/UbHV-vzF2oI/AAAAAAAAAuA/Gnd5sqevqro/s320/Alignment+can+be+tricky.png" width="320" /></a></div>
<div><b><span>Representation on the </span></b><b><span>Socio-Economic Committees (SEC) </span></b><b><span>and their terms of reference are currently the subject of discussion. Currently, this is what is envisaged.</span></b><br /><a name=''more''></a><b><span><o:p></o:p></span></b></div>
<div>           </p>
<div><span><span>§<span>&nbsp; </span></span></span><span>A Socio-Economic Committee (SEC) will be established in each city and county council area for planning and oversight of all local and community development programmes.<o:p></o:p></span></div>
<div><span><span>§<span>&nbsp; </span></span></span><span>SECs will have responsibility for developing a five-year City and County Local and Community plan, encompassing all state-funded local and community development interventions.<o:p></o:p></span></div>
<div><span><span>§<span>&nbsp; </span></span></span><span>A national policy on local and community development will be launched in advance of the 2014 local elections.<o:p></o:p></span></div>
<div><span><span>§<span>&nbsp; </span></span></span><span>It is intended that the SEC will be established in such a way that it will be eligible to be the structure through which LEADER is delivered in accordance with EU requirements.<o:p></o:p></span></div>
<div><span><span>§<span>&nbsp; </span></span></span><span>It is the view of the Alignment Steering Group that, to be effective, <span>the SEC should comprise no more than 15 members</span>, representing the local authority, local and community interests and appropriate State agencies. <o:p></o:p></span></div>
<div><span><span>§<span>&nbsp; </span></span></span><span>The local authority will provide executive support for the SEC, led by the County Manager/Director of Community and Enterprise. Decisions regarding the allocation of funding will rest with the SEC, while administrative functions, including payment of funds, performance monitoring, auditing and reporting will be undertaken by the county/city council.</span><span><o:p></o:p></span></div>
<p></div>
<div>           </p>
<div><b><span>The above points are taken from ‘</span></b><b><span>A Guide to Putting People First’ alongside<span>&nbsp; </span></span></b><b><span>extracts from a report written by Ian Dempsey, CEO of West Cork Development Partnership, from his meetings with officials and from the ‘Final Report of the Local Government/ Local Development Alignment Steering Group’. <o:p></o:p></span></b></div>
<div><b><span lang="EN-GB">Note: The Final Alignment Report acknowledged the European Court of Auditors 2010 report that among other things recommended limiting local authority involvement so that they do not dominate.<o:p></o:p></span></b></div>
<div><b><span>More information: All of these reports are available online.<o:p></o:p></span></b></div>
<p></div>
<p></p>', 'Representation on the Socio-Economic Committees (SEC) and their terms of reference are currently the subject of discussion. Currently, this is what is envisaged. § A Socio-Economic Committee (SEC) will be established in each city and county council area for planning and oversight of all local and community development programmes. § SECs will have responsibility for', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 169, 1, '2013-06-07T12:45:00Z', '2013-06-07T12:45:00Z', '2013-06-07T12:45:00Z')
