INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Issue 41 of Changing Ireland available online now', 'issue-41-of-changing-ireland-available-online-now', '<p></p>
<div>
<div><code></code></p>
<div data-config></div>
<p><code></code></div>
<div></div>
<div><code>Just click on the magazine cover to read&nbsp;</code></p>
<p>It&#8217;s now easier to get Changing Ireland then ever before. Here is a  quick &#8216;how to&#8217; guide on accessing the magazine using various technology.  </p>
<p><b>&nbsp;1. On your computer</b> &#8211; Just click the link below and you can scroll around and turn pages just as you would the print edition.</p>
<p><b>2. On your iPhone</b> &#8211; Select your browser. Log onto <a href="https://www.issuu.com/">www.issuu.com</a> and search &#8216;changingireland&#8217;. This will give you access to our library where you can select issue 40. Alternatively go to <a href="https://changingireland.ie/">www.changingireland.ie</a> and click the link on our homepage.<br /><b><br /></b><b>3. On your Android phone</b> &#8211; Go to <a href="https://changingireland.ie/">www.changingireland.ie</a> and select the link on our homepage.</p>
<p>Should you experience any problems, please give Robert a call at 061-458090. Print copies will be with readers soon.</p></div>
</div>', 'Just click on the magazine cover to read It’s now easier to get Changing Ireland then ever before. Here is a quick ‘how to’ guide on accessing the magazine using various technology. 1. On your computer – Just click the link below and you can scroll around and turn pages just as you would the', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 175, 1, '2013-01-08T09:48:00Z', '2019-09-13T10:45:52Z', '2013-01-08T09:48:00Z')
