INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('JUST PUBLISHED! 24 spectacular pages of local & community development work from around Ireland', 'just-published-24-spectacular-pages-of-local-community-development-work-from-around-ireland', '<p><span>It&#8217;s out! Packed with news &amp; features, the Winter 2012 edition of &#8216;Changing Ireland&#8217; has reached many thousands of readers around the country by post,&nbsp;</span></p>
<div role="article">
<div>
<div><span></span>is in Easons&nbsp;and you can flick through as easily as the paper version at <a href="https://www.issuu.com/changingireland.">https://issuu.com/changingireland/docs/changing_ireland-issue_41__winter_2012</a></div>
<div><span></span></p>
<div><span><b>LEAD ST</b></span></p>
<div><span><b>ORY</b>Politicans Promise The Sun, Moon &amp; Stars, but Martin delivers!</span><br /><span><br /></span><span><b>COLLECTIVE ACTION</b>Older People Speaking Out (Limerick)</span><br /><span>Tackling the Jobs Crisis (Wexford)</span><br /><span>16 Days of Action &#8211; What did you do?</span><br /><span>Santa joins protests against austerity!</span><br /><span><br /></span><span><b>INTERGENERATIONAL WORK</b>Monaghan&#8217;s Cross-Border initiative</span><br /><span>East Wall, Dublin&#8217;s pride of place win</span><br /><span><br /></span><span><b>COMMUNITY DEVELOPMENT</b>Focus on Kilkenny&nbsp;</span></div>
</div>
<p><span></span><span></span></p>
<div>
<div><span>Cats building cars &amp; finding work</span><br /><span><br /></span><span><b>SOCIAL INCLUSION</b>Preventing Early School Leaving</span><br /><span>Duhallow&#8217;s answer to anti-social behaviour: Boxing</span><br /><span>Youths go under the hood</span><br /><span>Fun flows for teenage revellers</span><br /><span>Anon &#8211; How we got the criminals out of our lives</span><br /><span><br /></span><span><b>INTERNATIONAL</b>Imagine if only 36% of your organisation&#8217;s funding came from Govt!</span><br /><span><br /></span><span><b>VOLUNTEERING</b></span><br /><span>West Cork interview</span><br /><span>Laois initiative</span><br /><span><br /></span><span><b>ALSO</b></span><br /><span>Conference briefs</span></div>
</div>
<p><span></span></div>
<div></div>
</div>
<div>
<div>
<div>
<div><a ajaxify="/ajax/flash/expand_inline.php?target_div=uh3txre11&amp;share_id=254472531346808&amp;max_width=403&amp;max_height=403&amp;context=timelineSingle" href="https://www.facebook.com/pages/Changing-Ireland/195484689356?ref=hl#" rel="async"><i></i><img decoding="async" alt="" src="https://fbexternal-a.akamaihd.net/safe_image.php?d=AQAHn_VCISjwn9F6&amp;w=155&amp;h=114&amp;url=http%3A%2F%2Fimage.issuu.com%2F121205122555-f555afd7c748470eafb1da9c5425c4a9%2Fjpg%2Fpage_1_thumb_large.jpg" /></a><a href="https://issuu.com/changingireland/docs/changing_ireland-issue_41__winter_2012" rel="nofollow noopener noreferrer" target="_blank"></a></p>
<div>
<div><a href="https://issuu.com/changingireland/docs/changing_ireland-issue_41__winter_2012" rel="nofollow noopener noreferrer" target="_blank">CHANGING IRELAND ISSUE 41</a></div>
<div><a href="https://issuu.com/changingireland/docs/changing_ireland-issue_41__winter_2012" rel="nofollow noopener noreferrer" target="_blank">issuu.com</a></div>
<div><a href="https://issuu.com/changingireland/docs/changing_ireland-issue_41__winter_2012" rel="nofollow noopener noreferrer" target="_blank">The national magazine of the Local and Community Development Programme</a></div>
</div>
<p><a href="https://issuu.com/changingireland/docs/changing_ireland-issue_41__winter_2012" rel="nofollow noopener noreferrer" target="_blank"></a></div>
