INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('A Taste of What’s To Come', 'a-taste-of-whats-to-come', '<p>&#8211;&gt;       </p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://1.bp.blogspot.com/-wFVVNrGqfV8/UKNtvnIYKJI/AAAAAAAAAro/tKVGQPHEulk/s1600/Screen+Shot+2012-11-14+at+10.08.20.png"><img loading="lazy" decoding="async" border="0" height="220" src="https://1.bp.blogspot.com/-wFVVNrGqfV8/UKNtvnIYKJI/AAAAAAAAAro/tKVGQPHEulk/s320/Screen+Shot+2012-11-14+at+10.08.20.png" width="320" /></a></td>
</tr>
<tr>
<td>Participants on the 2012 Work Taster Programme</td>
<td></td>
</tr>
</tbody>
</table>
<div></div>
<p>&#8211;&gt;     <b><span>Work-taster programme lands two participants permanent jobs in Ballymun</span></b>&nbsp; </p>
<div></div>
<div><span>Most employers hate sifting through CVs. It&#8217;s just black and white text to them. There&#8217;s no personal feeling or relationship with the person whose achievements and experience are listed within the pages.</span><span></span></div>
<div></div>
<div><span>What if you are from an area that the media has targeted as disadvantaged? Would you have the confidence to apply for a job?</span></p>
<p><span></span><br /><a name=''more''></a><span>&nbsp;</span><span></span></div>
<div></div>
<div><span>A programme in Ballymun that provides the long-term unemployed with training and real working experience saw two of the eight participants in the pilot retained by their employer.</span><span></span></div>
<div></div>
<div><span>“The barriers now down, the employer has had the opportunity to meet with these people, rather than having a CV on their desk from a person in Ballymun, says Fiona Descoteaux.</span><span></span></div>
<div></div>
<div><span>“They see who the person is and what they can deliver. The participant can build up a relationship with the employer. It gives them a chance that they wouldn&#8217;t have had before.”</span><span></span></div>
<div></div>
<div><span>The need for the programme grew out of necessity. The simple addition of a job placement at the end of a period of training has added an extra dimension to training courses.</span></div>
<div></div>
<div><span>“We&#8217;d been offering training programmes but we found while that the clients got something out of it, they then disappeared”, says Fiona </span><span></span></div>
<div></div>
<div><span>“We don&#8217;t always have a continuous relationship with the individual, so we wanted to make sure that we provide the individual with training &#8211; gaining the skills that they require &#8211; and also with experience in terms of the work placement so the programme that we are running now is focusing on a training component as well as a job placement.”</span></div>
<div></div>
<div><span>Such was the pilot’s success that 60 people applied for the 2012 programme. 20 people were lucky enough to get places.</span><span></span></div>
<div></div>
<div><span>Participants undertake 300 hours of FETAC level 3 training, split equally between communication training, spreadsheets and word processing. IKEA was the only employer for the pilot project but 2012 participants will have more choice.</span><span></span></div>
<div></div>
<div><span>“The key is having employers involved who are interested in employing people in their local community”, says Fiona.</span></div>
<div></div>
<div><span>“If we are supporting someone to change their life even slightly, I think that&#8217;s a fantastic achievement for the Partnership”, she added.</span><span></span></div>', '–> Participants on the 2012 Work Taster Programme –> Work-taster programme lands two participants permanent jobs in Ballymun Most employers hate sifting through CVs. It’s just black and white text to them. There’s no personal feeling or relationship with the person whose achievements and experience are listed within the pages. What if you are from', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 178, 1, '2012-11-14T10:11:00Z', '2019-09-13T10:46:01Z', '2012-11-14T10:11:00Z')
