INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('LCDP Progress Report published; community groups await “alignment” proposals', 'lcdp-progress-report-published-community-groups-await-alignment-proposals', '<div></div>
<p><span><span>         </span><span></span><span></span><span></span><span> </span><span></span><span>   </span><span></span><span> </span></span></p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://2.bp.blogspot.com/-ZyI0xrm8tWc/UE38Dfs5DiI/AAAAAAAAAqY/N03X8Vul9qA/s1600/Some+of+the+10,000+people+who+got+a+training+boost+through+the+LCDP+in+2011.png"><img loading="lazy" decoding="async" border="0" height="317" src="https://2.bp.blogspot.com/-ZyI0xrm8tWc/UE38Dfs5DiI/AAAAAAAAAqY/N03X8Vul9qA/s400/Some+of+the+10,000+people+who+got+a+training+boost+through+the+LCDP+in+2011.png" width="400" /></a></td>
</tr>
<tr>
<td><span><i>Some of the 10,000 people who got a training boost through the LCDP in 2011</i></span></td>
</tr>
</tbody>
</table>
<div><span><span lang="EN-GB"></span></span></div>
<p><span> </span></p>
<div><span><span lang="EN-GB">(1) This week Community Minister Phil Hogan is reportedly due to discuss his &#8220;alignment&#8221; proposals with Cabinet which could see local authorities gaining far more control over State-funded community and local development initiatives.&nbsp;</span></span></div>
<p><span><span></span></span></p>
<div><span><span lang="EN-GB"></span></span><br /><a name=''more''></a><span><span lang="EN-GB">He&#8217;s had the summer to digest a final report by his <a href="https://changingireland.blogspot.ie/2011/12/high-five-looking-at-alignment-of-local.html">expert group</a> on &#8220;alignment&#8221; and he&#8217;s expected to announce his proposals very soon. The Minister has found the going slow as he told &#8216;Changing Ireland&#8217; shortly after being elected that he&#8217;d make his views on this matter public in July of last year. Therefore, anticipation has built among thousands of workers who are trying to second-guess what&#8217;s in store for them and the communities they work with. The matter was <a href="https://changingireland.blogspot.ie/2011/12/seanad-debate-opposition-divided-over.html">debated in the Seanad</a> last November.</span></span></div>
<p><span><span></span></span></p>
<div><span><br /></span></div>
<p><span><span></span></span></p>
<div><span><a href="https://2.bp.blogspot.com/-05b_9Qak95U/UE36WpIuqjI/AAAAAAAAAqA/GAmRgIMxCqA/s1600/LCDP+Progress+Report+2011+COVER.png"><span><img loading="lazy" decoding="async" border="0" height="200" src="https://2.bp.blogspot.com/-05b_9Qak95U/UE36WpIuqjI/AAAAAAAAAqA/GAmRgIMxCqA/s200/LCDP+Progress+Report+2011+COVER.png" width="140" /></span></a><span lang="EN-GB">(2) Separately, Pobal last Friday published the full final report showing some of the chief outcomes from work carried out under the Local and Community Development Programme. The initial findings were first reported in <a href="https://www.issuu.com/changingireland/docs/changing_ireland_issue_39_web">the summer edition of &#8216;Changing Ireland&#8217;.</a></span></span></div>
<p><span></span></p>
<div><span><span lang="EN-GB">This new&nbsp;<a href="https://www.pobal.ie/Publications/Documents/LCDP%20Progress%20Report%202011.pdf">full report</a> is 114 pages in length. We&#8217;ve highlighted a few tables from the report here. Let us know your thoughts/views on the report, or on alignment! Leave your comments on <a href="https://www.facebook.com/pages/Changing-Ireland/195484689356">our Facebook page</a> or email: editor@changingireland.ie</span></span><br /><span><span lang="EN-GB"><br /></span></span><span><span lang="EN-GB"><i><b>&#8211; ALLEN MEAGHER</b></i></span></span></div>
<p><span><i><b></b></i></span></p>
<div><span><span lang="EN-GB"><br /></span></span></div>
<p><span></span></p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-EAQXqt0R17s/UE37hap2TVI/AAAAAAAAAqQ/q0-BQ3Dxo00/s1600/Employment+status+of+those+who+found+work+thru+the+LCDP+in+2011.png"><img loading="lazy" decoding="async" border="0" height="260" src="https://4.bp.blogspot.com/-EAQXqt0R17s/UE37hap2TVI/AAAAAAAAAqQ/q0-BQ3Dxo00/s400/Employment+status+of+those+who+found+work+thru+the+LCDP+in+2011.png" width="400" /></a></td>
</tr>
<tr>
<td>
<div><i>Employment status of those who found work thru the LCDP in 2011.</i></div>
</td>
</tr>
</tbody>
</table>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-nKgbSUJ8wXk/UE38wOLJCTI/AAAAAAAAAqg/0QgctElPbkg/s1600/Pobal-Beneficiary+Groups+of+LCDP+Goal+3.png"><img loading="lazy" decoding="async" border="0" height="203" src="https://4.bp.blogspot.com/-nKgbSUJ8wXk/UE38wOLJCTI/AAAAAAAAAqg/0QgctElPbkg/s400/Pobal-Beneficiary+Groups+of+LCDP+Goal+3.png" width="400" /></a></td>
</tr>
<tr>
<td><i><span>The LCDP has four goals, one of the most important being to support people to find work or help them set up small enterprises and become self-employed. Best of all, the Programme targets its resources at those most on the margins. Here are the findings of national evaluation by Pobal of work nationwide last year in pursuit of this key Goal.</span></i><br /><i><br /></i></td>
</tr>
</tbody>
</table>
<div></div>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-4ItBg_oMKZc/UE36jHlV7_I/AAAAAAAAAqI/A0PYsW62Low/s1600/Pobal-How+many+found+work+where-via+LCDP+in+2011.png"><img loading="lazy" decoding="async" border="0" height="263" src="https://3.bp.blogspot.com/-4ItBg_oMKZc/UE36jHlV7_I/AAAAAAAAAqI/A0PYsW62Low/s400/Pobal-How+many+found+work+where-via+LCDP+in+2011.png" width="400" /></a></td>
</tr>
<tr>
<td>    <span><i>How many found work and where in 2011 through the&nbsp;Local and Community Development Programme (LCDP) in 2011? Pobal have the answers to this and many more questions in their just published progress report on the Programme.</i></span>   </td>
</tr>
</tbody>
</table>
<div></div>', 'Some of the 10,000 people who got a training boost through the LCDP in 2011 (1) This week Community Minister Phil Hogan is reportedly due to discuss his “alignment” proposals with Cabinet which could see local authorities gaining far more control over State-funded community and local development initiatives. He’s had the summer to digest a', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 180, 1, '2012-09-10T14:48:00Z', '2012-09-10T14:48:00Z', '2012-09-10T14:48:00Z')
