INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Track down LCDP projects around the country', 'track-down-lcdp-projects-around-the-country', '<div><a href="https://4.bp.blogspot.com/-Jbru15FqR18/UEoHDvWNFuI/AAAAAAAAApg/clLZTlOSD38/s1600/MAP+OF+LDCs.png"><img loading="lazy" decoding="async" border="0" height="210" src="https://4.bp.blogspot.com/-Jbru15FqR18/UEoHDvWNFuI/AAAAAAAAApg/clLZTlOSD38/s320/MAP+OF+LDCs.png" width="320" /></a></div>
<p><span>Did you know Changing Ireland has the most  comprehensive database of LCDP projects in the country? We can tell you where  they are, how to contact them and you can even virtually stand outside  their front door using our map. Above is our &#8216;how to&#8217; guide to using the map.</span></p>', 'Did you know Changing Ireland has the most comprehensive database of LCDP projects in the country? We can tell you where they are, how to contact them and you can even virtually stand outside their front door using our map. Above is our ‘how to’ guide to using the map.', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 181, 1, '2012-09-07T14:39:00Z', '2012-09-07T14:39:00Z', '2012-09-07T14:39:00Z')
