INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Do it yourself! Cavan-Monaghan LEADER paves the way for local festivals', 'do-it-yourself-cavan-monaghan-leader-paves-the-way-for-local-festivals', '<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-14dikbMclP0/UA5sfW4roZI/AAAAAAAAAnE/yS8Ik-ahS_s/s1600/hulks.jpg"><img loading="lazy" decoding="async" border="0" height="166" src="https://3.bp.blogspot.com/-14dikbMclP0/UA5sfW4roZI/AAAAAAAAAnE/yS8Ik-ahS_s/s320/hulks.jpg" width="320" /></a></td>
</tr>
<tr>
<td>Casteblayney goes green in their successful attempt to break the Guinness world record for the most Hulks in one place. Photo: Glenn Murphy who is a voluntary member of the festivals committee in Castleblayney.</td>
</tr>
</tbody>
</table>
<p>Cavan-Monaghan LEADER have helped to find a solution to a lack of sponsorship and sustain festivals and events in the two counties for years to come, by assisting in the purchase of equipment that would normally have to be hired at at a high cost.<br /><a name=''more''></a></p>
<p>After they were approached by local festival and event groups, regarding support in hiring equipment and assistance in marketing, public information events were held to raise awareness.</p>
<p>&#8216;Castleblayney Community and Enterpise in Monaghan&#8217; formed a band comprised of six local festival groups in order to purchase the relevant equipment which could be shared among them.<br />  <span lang="EN-IE">&nbsp;</span><br /><span lang="EN-IE">‘Castleblayney Festivals Group’ were helped with the purchase of festival infrastructure equipment including an all weather public address system, crowd control barriers, street cones, a small marquee and semi-permanent signs for each main access road to the town.&nbsp;&nbsp;&nbsp;</span></p>
<div><a href="https://3.bp.blogspot.com/-14dikbMclP0/UA5sfW4roZI/AAAAAAAAAnE/yS8Ik-ahS_s/s1600/hulks.jpg"><br /></a></div>
<p>               <span lang="EN-IE">Each of the six festivals also received support for local advertising, promotional banners, flyers and inclusion on a festival calendar which would be used to promote all events during the following year.&nbsp; </span>   <span lang="EN-IE">&nbsp;</span></p>
<div><span lang="EN-IE">Diverse events and festivals </span><span lang="EN-IE">that have benefited from the funding have included agricultural shows, summer festivals, drama festivals, pipe band parades, fun sports events, film festivals, clan gatherings, heritage events, successful world record attempts and bog snorkelling. </span></div>
<div></div>
<div><span lang="EN-IE">Cavan-Monaghan LEADER has promoted this approach as a model of best practice to help sustain community festivals and events by keeping their running costs to a minimum, whilst maximising promotional opportunities.&nbsp; &nbsp;Five lead groups have accessed approximately €250,000 in funding support for the benefit of a total of 23 individual festivals and events from Cavan and Monaghan to date. </span></div>', 'Casteblayney goes green in their successful attempt to break the Guinness world record for the most Hulks in one place. Photo: Glenn Murphy who is a voluntary member of the festivals committee in Castleblayney. Cavan-Monaghan LEADER have helped to find a solution to a lack of sponsorship and sustain festivals and events in the two', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 182, 1, '2012-07-24T08:43:00Z', '2019-09-13T10:46:53Z', '2012-07-24T08:43:00Z')
