INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Mid-West substance misuse support service launched', 'mid-west-substance-misuse-support-service-launched', '<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://4.bp.blogspot.com/-yIVhX2PuM-Q/UAa-7cokCSI/AAAAAAAAAmA/I4HvqKxN7a8/s1600/Screen+Shot+2012-07-18+at+14.48.28.png"><img loading="lazy" decoding="async" border="0" height="171" src="https://4.bp.blogspot.com/-yIVhX2PuM-Q/UAa-7cokCSI/AAAAAAAAAmA/I4HvqKxN7a8/s320/Screen+Shot+2012-07-18+at+14.48.28.png" width="320" /></a></td>
</tr>
<tr>
<td>L-R: Chairperson of the Regional Drug Task Force Mick Lacey, Minister of State Jan O&#8217;Sullivan, Mayor of Limerick Gerry McLoughlin and Project Manager at CSMT, Maria Finn</td>
</tr>
</tbody>
</table>
<p>A new service which aims to provide a free support service to under 18&#8217;s, who are affected by substance misuse in the Mid-West, has been launched in Limerick City.</p>
<p>The Community Substance Misuse Team will provide one to one, &#8220;specifically tailored&#8221; programmes to youths, as well as personal development, group, educational and parenting support programmes.</p>
<p>Opening the service, Minister of State Jan O&#8217;Sullivan said there was a real need for the service within the region, while CASP Project Manager Maria Finn added, &#8220;It&#8217;s about positively reinforcing the resources that people have and communities have to support their own members. There are brilliant services already here but sometimes people get lost between the gaps. We want people to realise they are more than the problem itself.&#8221;</p>
<p>For more information visit their into their office on the 3rd floor, Theatre Court, 15 Lower Mallow St., Limerick. </p>', 'L-R: Chairperson of the Regional Drug Task Force Mick Lacey, Minister of State Jan O’Sullivan, Mayor of Limerick Gerry McLoughlin and Project Manager at CSMT, Maria Finn A new service which aims to provide a free support service to under 18’s, who are affected by substance misuse in the Mid-West, has been launched in Limerick', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 183, 1, '2012-07-23T08:25:00Z', '2019-09-13T10:47:18Z', '2012-07-23T08:25:00Z')
