INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ryan Howard of East Cork says – Think positive!', 'ryan-howard-of-east-cork-says-think-positive', '<p></p>
<div></div>
<div><a href="https://2.bp.blogspot.com/-QeDQbBMk72Q/T_6aEV5BvxI/AAAAAAAAAls/58xgQX1cIbw/s1600/Positive+Thinking.jpg"><img loading="lazy" decoding="async" border="0" height="212" src="https://2.bp.blogspot.com/-QeDQbBMk72Q/T_6aEV5BvxI/AAAAAAAAAls/58xgQX1cIbw/s320/Positive+Thinking.jpg" width="320" /></a><b><span lang="EN-GB">PROFILE INTERVIEW&nbsp;</span></b></div>
<div><b><span lang="EN-GB"><br /></span></b></div>
<div><b><span lang="EN-GB">Who’s your hero?</span></b></div>
<div><span lang="EN-GB">Nelson Mandela. And my late father was a great man, a hard worker.</span></div>
<div></div>
<div><b><span lang="EN-GB">Nationally, what do we need more of?<o:p></o:p></span></b></div>
<div><span lang="EN-GB">We need to move away from the negative and begin focussing in on the positives. There’s not enough good news being reported and it has a subliminal effect on us all.</span></div>
<div></div>
<div><b><span lang="EN-GB"></span></b></div>
<p><a name=''more''></a><b>Nationally, we need less?<o:p></o:p></b></p>
<div><span lang="EN-GB">Negativity.</span></div>
<div></div>
<div><b><span lang="EN-GB">Why did you get involved in community development?<o:p></o:p></span></b></div>
<div><span lang="EN-GB">I worked in the private sector and travelled with the food industry. I liked the buzz and the adrenalin, then I took some time off, went back to college and studied rural development. I fell for it because it was so positive, constructive and it made a difference. Then I found myself volunteering in Macroom for three weeks, which turned into one year.</span></div>
<div><span lang="EN-GB"><br /></span></div>
<div><span lang="EN-GB"></span></div>
<div><b><span lang="EN-GB">What are the top four issues in Ireland today?<o:p></o:p></span></b></div>
<div><span lang="EN-GB">1.<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span><span lang="EN-GB">Employment.</span></div>
<div><span lang="EN-GB">2.<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span><span lang="EN-GB">Suicide – particularly among young men.</span></div>
<div><span lang="EN-GB">3.<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span><span lang="EN-GB">Isolation and lack of community contact within the last decade, although there’s a sense now that it’s improving.</span></div>
<div><span lang="EN-GB">4.<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span></span><span lang="EN-GB">The Economy – there’s a growing sense of frustration.</span></div>
<p></p>
<div></div>
<div><b><span lang="EN-GB">What difference has it made to you being involved in the Local Development Company?<o:p></o:p></span></b></div>
<div><span lang="EN-GB">We are making a difference. Sometimes, you’re working with someone who has a dream but fears for their future… Sometimes, you start with communities who start with very little and you see them develop. It’s also very challenging, there are more barriers than there are solutions sometimes and you’re always thinking of ways to get around barriers. The job never ends.</span></div>
<div><span lang="EN-GB"><br /></span></div>
<div><span lang="EN-GB"></span></div>
<div><b><span lang="EN-GB">What are you reading at the moment?<o:p></o:p></span></b></div>
<div><span lang="EN-GB">Jeremy Clarkson’s “Around a Bend”.</span></div>
<div></div>
<div><span lang="EN-GB"><o:p><br /></o:p></span></div>
<p></p>', 'PROFILE INTERVIEW Who’s your hero? Nelson Mandela. And my late father was a great man, a hard worker. Nationally, what do we need more of? We need to move away from the negative and begin focussing in on the positives. There’s not enough good news being reported and it has a subliminal effect on us', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 185, 1, '2012-07-12T08:38:00Z', '2019-09-13T10:47:33Z', '2012-07-12T08:38:00Z')
