INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('New textbook on Community Development', 'new-textbook-on-community-development', '<p></p>
<div><a href="https://2.bp.blogspot.com/-mkh_abPRvgI/T-CQm4zXD3I/AAAAAAAAAjc/ZTnm7ESOR2k/s1600/CD+book+2012.JPG"><img loading="lazy" decoding="async" border="0" height="320" src="https://2.bp.blogspot.com/-mkh_abPRvgI/T-CQm4zXD3I/AAAAAAAAAjc/ZTnm7ESOR2k/s320/CD+book+2012.JPG" width="239" /></a></div>
<div><b><span>A new textbook introducing the theories and practices of community development, complimented by case-studies of Irish success stories, has been published.</span></b></div>
<div><span><b>In 250-pages ‘</b><i>Community Development: Theory, Policy and Practice</i>’<b> achieves a lot, for example it:</b></span><br /><a name=''more''></a></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Shows how community development tackles social disadvantage and is a powerful force for social change in Ireland.</span></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Looks critically at the relationship between policy and practice.</span></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Shows what’s necessary for effective and sustainable community development in our rapidly changing society.</span></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Offers solutions to current issues and challenges in Ireland.</span></div>
<div><span>·<span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span>Showcases models of best practice in various community development settings.</span></div>
<div><span>It also highlights ideas that are currently shaping community development projects and programmes nationally. </span></div>
<div><span>The book was co-edited by Dr Ashling Jackson and Dr Colm O&#8217;Doherty with third-level students in mind but it should also be of interest to community workers and volunteers/activists in local communities. </span></div>
<p><span>It’s published by&nbsp;Gill &amp; Macmillan and was launched recently by Fergus Finlay of Barnardos. There is only one sting in the tail – it’s priced at €29.99. Ask your local library to buy a copy.</span></p>
<div><a href="https://3.bp.blogspot.com/-w2VeSGzQEHQ/T-rPdVmgQ8I/AAAAAAAAAkM/0km6QTkuu9s/s1600/CD+book+launch+official+photo.jpg"><img loading="lazy" decoding="async" border="0" height="213" src="https://3.bp.blogspot.com/-w2VeSGzQEHQ/T-rPdVmgQ8I/AAAAAAAAAkM/0km6QTkuu9s/s320/CD+book+launch+official+photo.jpg" width="320" /></a></div>
<p><span><br /></span></p>', 'A new textbook introducing the theories and practices of community development, complimented by case-studies of Irish success stories, has been published. In 250-pages ‘Community Development: Theory, Policy and Practice’ achieves a lot, for example it: · Shows how community development tackles social disadvantage and is a powerful force for social change in Ireland. · Looks', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 186, 1, '2012-07-12T08:30:00Z', '2012-07-12T08:30:00Z', '2012-07-12T08:30:00Z')
