INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('476 new businesses sprout in Donegal  – with a survival rate of 60% after three years', '476-new-businesses-sprout-in-donegal-with-a-survival-rate-of-60-after-three-years', '<p></p>
<div>    </div>
<div>
<table cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-sat10wkYRkk/T-B6rdriuNI/AAAAAAAAAhA/fM42kOuFolc/s1600/Michael+Conway.jpg"><img loading="lazy" decoding="async" border="0" height="240" src="https://3.bp.blogspot.com/-sat10wkYRkk/T-B6rdriuNI/AAAAAAAAAhA/fM42kOuFolc/s320/Michael+Conway.jpg" width="320" /></a></td>
</tr>
<tr>
<td>  <span><span>AIB’s Jim McLaughlin, DLDC chair Jim Slevin and winner Michael Conway.&nbsp;</span></span>&nbsp;</td>
</tr>
</tbody>
</table>
<p><b><span lang="EN-GB">Ann Styles reports</span></b></div>
<div><span lang="EN-GB">Entrepreneurs in Donegal have access to a wealth of information and support from their Local Development Company (LDC).</span></div>
<div><span lang="EN-GB">From Start Your Own Business (SYOB) courses to mentoring and workshops, the company provides a comprehensive support system for people, many of who have been long-term unemployed, with a desire to set up their own business. The LDC has two full time project officers who co-ordinate the service which has supported over 1900 people to date. </span></div>
<p><a name=''more''></a></p>
<div><span lang="EN-GB">Donegal LDC Enterprise Officer, Louise Brogan said that, since 2009, Donegal LDC has supported 476 people in setting up new businesses with current trends in areas such as sports and leisure, driving instruction and graphic design. Of the 476 businesses, Louise estimates that at least 60% are still in business.</span></div>
<div><span lang="EN-GB">Louise and her colleagues believe that the future for many people lies in self-employment and that one-to-one support is key regardless of the person’s background.</span></div>
<div><span lang="EN-GB">One man who would agree is Enterprise Award winner Michael Conway: “Without their support I wouldn’t be here, they helped me immensely.”</span></div>
<div><span lang="EN-GB">Michael </span>began with window cleaning and has expanded to include light DIY, painting and decorating, and exterior cleaning.</div>
<div><span lang="EN-GB">The supports offered to budding entrepreneurs include a SYOB course, one-to-one appointments, preparation of a business plan and cash-flow projections, mentoring and a bookkeeping course.</span></div>
<div><span lang="EN-GB">The mentoring provided by the enterprise scheme was a vital part of the supports offered said Michael as it prevented you from feeling isolated and gave you the assurance that someone was there to hear your concerns.</span></div>
<div><span lang="EN-GB">The enterprise scheme also provides workshops to improve awareness of, for instance: Sales techniques, marketing strategies, and how to prepare a health and safety statement.</span></div>
<div><span lang="EN-GB">“These courses and workshops save people money by helping them to do it on their own.” said Louise.</span></div>
<div><span lang="EN-GB">Michael agreed, adding that he went to every workshop on offer and found them highly informative, allowing him to garner knowledge in many relevant topics such as tax returns and Internet use. </span></div>
<div><span lang="EN-GB">Returning to work was important to Michael, who had been out of the workplace for some time while battling cancer. He felt it was necessary to alter people’s perception of him as ‘ill’ and instead be seen as capable of contributing to the work sphere. He first contacted Donegal LDC in 2008 and four years on he employs two people, has completed training-for-trainers and regularly passes on work to other self-employed people in his area. He is also the winner of the Donegal LDC Enterprise Award for 2011.</span></div>
<div><span lang="EN-GB">Donegal LDC faces a number of challenges in delivering this service. The catchment area is vast and predominantly rural which limits employment opportunities in the county. </span></div>
<div><span lang="EN-GB">Another challenge is the high volume of prospective clients, coupled with a wide range of educational backgrounds and life-experiences and there are also issues with viability and displacement due to overlaps in business ideas.</span></div>
<div><span lang="EN-GB">In response, Donegal LDC are putting new structures in place to reach a wider number of people, they’re redesigning the business start-ups course and they’re running an ideas generation workshop. </span></div>
<div><span lang="EN-GB">Michael encourages people to “look outside the box” and to give Donegal LDC a call.</span></div>
<div><b>For more info, contact Louise Brogan on 086-812-4250. E: lbrogan@dldc.org<span lang="EN-GB"></span></b></div>', 'AIB’s Jim McLaughlin, DLDC chair Jim Slevin and winner Michael Conway. Ann Styles reports Entrepreneurs in Donegal have access to a wealth of information and support from their Local Development Company (LDC). From Start Your Own Business (SYOB) courses to mentoring and workshops, the company provides a comprehensive support system for people, many of who', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 194, 1, '2012-07-02T07:00:00Z', '2019-09-13T10:47:47Z', '2012-07-02T07:00:00Z')
