INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Offaly men changing their lives', 'offaly-men-changing-their-lives', '<p></p>
<table align="center" cellpadding="0" cellspacing="0">
<tbody>
<tr>
<td><a href="https://3.bp.blogspot.com/-uN02UTiIzrM/T-Bhxcp8geI/AAAAAAAAAgY/9wf6wN3IzyQ/s1600/Keith+Walsh+and+Michael+Egan+CROPPED.JPG"><img loading="lazy" decoding="async" border="0" height="320" src="https://3.bp.blogspot.com/-uN02UTiIzrM/T-Bhxcp8geI/AAAAAAAAAgY/9wf6wN3IzyQ/s320/Keith+Walsh+and+Michael+Egan+CROPPED.JPG" width="257" /></a></td>
</tr>
<tr>
<td>Keith Walsh and Michael Egan</td>
</tr>
</tbody>
</table>
<p></p>
<div>  <b><span lang="EN-GB">Interviews by Robert McNamara</span></b>&nbsp; <b><span lang="EN-GB"><br /></span></b></div>
<div></div>
<div><b><span lang="EN-GB">&nbsp;Keith Walsh and Michael Egan from Clara both did the 16 month programme and are continuing on with further education and community involvement. Community workers first approached Keith and Michael about the programme and now they are themselves recommending it to people they meet.</span></b></div>
<p><a name=''more''></a></p>
<div></div>
<div><b><u><span lang="EN-IE">Keith Walsh (27)</span></u></b></div>
<div><b><span lang="EN-GB">What got you involved?</span></b></div>
<div><span lang="EN-GB">I wanted to do a course.</span></div>
<div></div>
<div><b><span lang="EN-GB">How have you benefited from the programme?</span></b></div>
<div><span lang="EN-GB">I got my FETAC Level 3 &amp; 4, which is something I wouldn’t have done.</span></div>
<div><span lang="EN-IE">It was a great help on the computers and I’m now designing posters for the Men’s Shed. </span></div>
<div><span lang="EN-GB">I’ve also taken on a new role with Tús.</span></div>
<div></div>
<div><b><span lang="EN-GB">What were your favourite parts?</span></b></div>
<div><span lang="EN-GB">The social aspect and the benefit of the education were the best parts. </span><span lang="EN-IE">We went on trips to Moate Business College, the FAS Training Centre and the Men’s Shed in Galway, places I wouldn’t normally get to see. It was good for team-building. Now I’ve got used to getting involved in things.</span></div>
<div></div>
<div></div>
<div><b><u><span lang="EN-IE">Michael Egan aged 37</span></u></b></div>
<div><b><span lang="EN-GB">What got you involved?</span></b></div>
<div><span lang="EN-GB">I attended the course after I was outreached by Karen McDonagh (youth worker) and Catherine Power (development worker) and they asked me to join the course.</span></div>
<div></div>
<div><b><span lang="EN-GB">How have you benefited from the programme?</span></b></div>
<div><span lang="EN-GB">It h</span><span lang="EN-IE">elped me a lot with maths and I picked up a lot of skills on Microsoft Word. </span><span lang="EN-GB">It’s opened up doors for me to go onto the next level, which is Level 5 college. I will do level 5. I&#8217;m ready for the next step and with more confidence. </span></div>
<div><span lang="EN-IE">I’m confident to get going again. I’d got into a rut at home. </span></div>
<div></div>
<div><b><span lang="EN-GB">What were your favourite parts?</span></b></div>
<div><span lang="EN-GB">Drama was interesting &#8211; I was nervous at the beginning but I was surprised how good it was and it built up my confidence.</span></div>
<div><span lang="EN-IE">I’ve recommended the course to other people and the Family Resource Centre is local, a place where young and old can go.</span></div>
<div></div>
<div align="center"></div>
<div><b><span lang="EN-GB">210 WORDS</span></b></div>
<div><b><span lang="EN-GB">In Brief: Offaly’s ‘Way Forward Project’</span></b></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><span lang="EN-GB">Many of the participants in ‘The Way Forward Project’ had not found work during the ‘boom’ and were finding it even more difficult now.</span></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; People who completed the programme told ‘Changing Ireland’ they were attracted to it because transport wasn’t an issue. It was held in their town/area. </span></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><span lang="EN-GB">Led by Offaly Local Development Company, the project was set up in September 2010 and lasted until December 2011.</span><span lang="EN-GB"></span></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </span><span lang="EN-GB">Offaly LDC made the connections with local people through the strong bonds of trust built up by community workers in Family Resource Centres and Community Development Projects. This was one of the Programme strengths.</span></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Four programmes were developed namely: Foundations for Change in Birr, the Career Skills Programme in Clara, the Career Development Programme in Tullamore, and the Men&#8217;s Project in Edenderry. </span></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Funding came from the Department of Social Protection, Offaly LDC and the VEC. </span><span lang="EN-GB">Many of the key players were on the Social Inclusion Measures committee and this became the steering group for the project.</span><span lang="EN-GB"></span></div>
<div><span lang="EN-GB">•&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; For community development workers and students interested to learn more, check ‘Changing Ireland’s news blog where we’ve posted a link to a more detailed PDF presentation on what made the programme work and the challenges that it sought to overcome.</span></div>', 'Keith Walsh and Michael Egan Interviews by Robert McNamara Keith Walsh and Michael Egan from Clara both did the 16 month programme and are continuing on with further education and community involvement. Community workers first approached Keith and Michael about the programme and now they are themselves recommending it to people they meet. Keith Walsh', '', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[]', '', 196, 1, '2012-06-28T08:00:00Z', '2012-06-28T08:00:00Z', '2012-06-28T08:00:00Z')
